//! Site-wide constants: origin, locales, and the Tailwind-driven
//! stylesheet.
//!
//! The stylesheet is generated by running the Tailwind CLI over the same
//! `src/styles/globals.css` and `tailwind.config.ts` the Next.js build
//! uses, so the Rust output is styled identically. See `build-css.sh`.

/// Canonical origin. Every absolute URL in the generated HTML uses this.
pub const ORIGIN: &str = "https://frankbot.org";

/// Brand name used in `<title>` and metadata.
pub const SITE_NAME: &str = "OpenClaw";

/// Locales the site serves, in the order the layout lists them.
pub const LOCALES: [&str; 3] = ["ja", "zh", "en"];

/// The order `getAvailableLocales()` returns locales in.
///
/// The Next.js helper uses `['en', 'ja', 'zh']`, which is *not* the
/// same order as the layout's hreflang alternates. The fallback notice
/// on an article page lists the other locales in this order.
pub const AVAILABLE_LOCALES: [&str; 3] = ["en", "ja", "zh"];

/// The locale `x-default` and the root redirect point at.
pub const DEFAULT_LOCALE: &str = "ja";

/// Blog list page size, matching `POSTS_PER_PAGE` in `src/lib/blog.ts`.
pub const POSTS_PER_PAGE: usize = 10;
